import numpy as np
import math
import time

def circle_packing21() -> np.ndarray:
    target = 21
    tol = 1e-10

    def nonoverlap_with_all(x, y, r, circles, W, H, allow_tangency=True):
        # Inside rectangle
        if x - r < -1e-9 or y - r < -1e-9 or x + r > W + 1e-9 or y + r > H + 1e-9:
            return False
        # Check 2r <= respective dimension when tangent to a vertical or horizontal wall is expected elsewhere
        for (cx, cy, cr) in circles:
            d = math.hypot(x - cx, y - cy)
            if allow_tangency:
                if d < r + cr - 1e-9:
                    return False
            else:
                if d <= r + cr - 1e-9:
                    return False
        return True

    # Solve for circle tangent to two orthogonal walls (corner) and one existing circle j
    def candidate_WWC(cj, W, H, corner, circles):
        xj, yj, rj = cj
        # Transform so corner is Left-Bottom, i.e., (x, y) = (r, r)
        def to_LB(x, y, corner, W, H):
            if corner == 'LB':
                return x, y
            elif corner == 'RB':
                return W - x, y
            elif corner == 'LT':
                return x, H - y
            else:  # 'RT'
                return W - x, H - y

        def from_LB(x, y, corner, W, H):
            if corner == 'LB':
                return x, y
            elif corner == 'RB':
                return W - x, y
            elif corner == 'LT':
                return x, H - y
            else:  # 'RT'
                return W - x, H - y

        xjt, yjt = to_LB(xj, yj, corner, W, H)
        rmax = min(W, H) / 2.0 - 1e-12

        def f(r):
            return math.hypot(r - xjt, r - yjt) - rj - r

        # Need sign change on [0, rmax]
        f0 = f(0.0)
        f1 = f(rmax)
        if not (np.isfinite(f0) and np.isfinite(f1)):
            return None
        if f0 <= 0 or f1 >= 0:
            return None
        lo, hi = 0.0, rmax
        for _ in range(60):
            mid = 0.5 * (lo + hi)
            fm = f(mid)
            if fm > 0:
                lo = mid
            else:
                hi = mid
        r = 0.5 * (lo + hi)
        x, y = from_LB(r, r, corner, W, H)
        # Check non-overlap with all (allow slight tangency with cj)
        if not nonoverlap_with_all(x, y, r, [c for c in circles if c is not cj], W, H, allow_tangency=True):
            return None
        return (x, y, r)

    # Transform to use Left-wall solver for any wall
    def wall_transform(x, y, W, H, wall):
        if wall == 'L':
            def back(xx, yy): return xx, yy, W, H
            return x, y, W, H, back
        elif wall == 'R':
            def back(xx, yy): return W - xx, yy, W, H
            return W - x, y, W, H, back
        elif wall == 'B':
            # swap axes: xt = y, yt = x; dims swap
            def back(xx, yy): return yy, xx, W, H
            return y, x, H, W, back
        else:  # 'T'
            # reflect y then swap: xt = H - y, yt = x
            def back(xx, yy): return yy, H - xx, W, H
            return H - y, x, H, W, back

    # Solve for circles tangent to a vertical Left wall (x = r) and two existing circles i, j (externally)
    def vertical_WCC_solutions(ci, cj, Wt, Ht):
        xi, yi, ri = ci
        xj, yj, rj = cj
        eps = 1e-12
        sols = []

        if abs(yj - yi) > eps:
            alpha = (ri - rj - (xj - xi)) / (yj - yi)
            beta = (ri * ri - rj * rj - xi * xi + xj * xj - yi * yi + yj * yj) / (2.0 * (yj - yi))
            A = alpha
            B = beta - yi
            a = A * A
            b = 2.0 * (A * B - xi - ri)
            c = xi * xi + B * B - ri * ri
            # Solve a r^2 + b r + c = 0
            if abs(a) < eps:
                if abs(b) > eps:
                    r = -c / b
                    if np.isfinite(r):
                        yt = alpha * r + beta
                        if r > eps and 2 * r <= Wt + 1e-12 and yt >= r - 1e-12 and yt <= Ht - r + 1e-12:
                            sols.append((r, yt))
            else:
                disc = b * b - 4.0 * a * c
                if disc >= -1e-12:
                    disc = max(0.0, disc)
                    sqrtD = math.sqrt(disc)
                    for sgn in (-1.0, 1.0):
                        r = (-b + sgn * sqrtD) / (2.0 * a)
                        if not np.isfinite(r):
                            continue
                        yt = alpha * r + beta
                        if r > eps and 2 * r <= Wt + 1e-12 and yt >= r - 1e-12 and yt <= Ht - r + 1e-12:
                            sols.append((r, yt))
        else:
            # yj == yi; solve directly for r from difference
            den = 2.0 * (xj - xi - (ri - rj))
            if abs(den) > eps:
                r = ((ri * ri - rj * rj) - (xi * xi - xj * xj)) / den
                if np.isfinite(r):
                    temp = (r + ri) * (r + ri) - (r - xi) * (r - xi)
                    if temp >= -1e-12:
                        temp = max(0.0, temp)
                        root = math.sqrt(temp)
                        y1 = yi + root
                        y2 = yi - root
                        for yt in (y1, y2):
                            if r > eps and 2 * r <= Wt + 1e-12 and yt >= r - 1e-12 and yt <= Ht - r + 1e-12:
                                sols.append((r, yt))
        # Return list of (xt, yt, r) where xt = r
        out = []
        for (r, yt) in sols:
            out.append((r, yt, r))
        return out

    def candidates_WCC(ci, cj, W, H, wall, circles):
        # Transform to Left-vertical
        xi_t, yi_t, Wt, Ht, back = wall_transform(ci[0], ci[1], W, H, wall)
        xj_t, yj_t, _, _, _ = wall_transform(cj[0], cj[1], W, H, wall)
        ci_t = (xi_t, yi_t, ci[2])
        cj_t = (xj_t, yj_t, cj[2])
        sols_t = vertical_WCC_solutions(ci_t, cj_t, Wt, Ht)
        res = []
        for xt, yt, rt in sols_t:
            # Map back
            xb, yb, _, _ = back(xt, yt)
            # Feasibility: check distances exactly to i and j near tangency
            ok = True
            di = math.hypot(xb - ci[0], yb - ci[1])
            dj = math.hypot(xb - cj[0], yb - cj[1])
            if abs(di - (rt + ci[2])) > 1e-6 or abs(dj - (rt + cj[2])) > 1e-6:
                ok = False
            if not ok:
                continue
            if not nonoverlap_with_all(xb, yb, rt, [c for c in circles if c is not ci and c is not cj], W, H, allow_tangency=True):
                continue
            res.append((xb, yb, rt))
        return res

    # Try several aspect ratios W + H = 2
    best_sum = -1.0
    best = None
    aspect_Ws = [1.0, 1.25, 0.75, 1.35, 0.65, 1.15, 0.85]
    for W in aspect_Ws:
        H = 2.0 - W
