            continue

        # --- Transplanted donor component: partition-based shelf packing ---
        # Generate partitions of 21 into 4-7 layers, nonincreasing
        candidates = []
        for layers in range(4, 8):
            def generate_partitions(n, m, min_val=1):
                if m == 1:
                    return [[n]] if n >= min_val else []
                partitions = []
                start = min(n - (m - 1) * min_val, n - m + 1)
                for first in range(start, min_val - 1, -1):
                    for rest in generate_partitions(n - first, m - 1, first):
                        partitions.append([first] + rest)
                return partitions
            for p in generate_partitions(target, layers, 1):
                if sum(p) == target and len(p) == layers:
                    candidates.append(p)

        seen = set()
        unique_candidates = []
        for c in candidates:
            t = tuple(c)
            if t not in seen:
                seen.add(t)
                unique_candidates.append(c)

        # Evaluate each partition
        for partition in unique_candidates:
            S = sum(1.0 / l for l in partition)
            c = 1.0 / (1.0 + S)
            r_list = [c / l for l in partition]
            layer_data = list(zip(partition, r_list))
            layer_data.sort(key=lambda x: -x[1])  # descending
            m_sorted, r_sorted = zip(*layer_data)

            circles = []
            y_base = 0.0
            for m, r in zip(m_sorted, r_sorted):
                y_center = y_base + r
                for j in range(m):
                    x_center = r + 2.0 * r * j
                    circles.append((x_center, y_center, r))
                y_base += 2.0 * r

            circles = np.array(circles, dtype=float)
            # Safety shrink
            circles[:, 2] = np.maximum(0.0, circles[:, 2] * (1.0 - 1e-12))
            # Translate
            min_x = np.min(circles[:, 0] - circles[:, 2])
            min_y = np.min(circles[:, 1] - circles[:, 2])
            circles[:, 0] -= min_x
            circles[:, 1] -= min_y

            # Validate bounding rectangle
            max_x = np.max(circles[:, 0] + circles[:, 2])
            max_y = np.max(circles[:, 1] + circles[:, 2])
            width = max_x - min_x
            height = max_y - min_y
            if width + height <= 2.0 + 1e-9:
                total_rad = np.sum(circles[:, 2])
                if total_rad > best_sum:
                    best_sum = total_rad
                    best = circles.copy()
        # --- End of transplant ---

        # Fallback: grid-based if no valid layout from partitioning
        if best is None:
