            def build_with_tangencies(W, H):
                circles = []

                # Seed with up to four small corner circles
                base_r = 0.11 * min(W, H)
                corner_centers = [(base_r, base_r),
                                  (W - base_r, base_r),
                                  (base_r, H - base_r),
                                  (W - base_r, H - base_r)]
                for (cx, cy) in corner_centers:
                    ok = True
                    for (x, y, r) in circles:
