                    cx, cy = W * 0.5, H * 0.5
                    circles.append((cx, cy, min(r0, cx, cy, W - cx, H - cy)))

                # Iteratively add best tangent candidates
                max_iters = 500
                while len(circles) < target and max_iters > 0:
                    max_iters -= 1
                    best = None
                    best_r = -1.0

                    # WWC: two orthogonal walls + one circle
                    for j, cj in enumerate(circles):
                        for corner in ('LB', 'RB', 'LT', 'RT'):
                            cand = candidate_WWC(cj, W, H, corner, circles)
                            if cand is None:
                                continue
                            x, y, r = cand
                            if r > best_r + 1e-12 and nonoverlap_with_all(x, y, r, circles, W, H, allow_tangency=True):
                                best = cand
                                best_r = r

                    # WCC: one wall + two circles
                    n = len(circles)
                    for i in range(n):
                        for j in range(i + 1, n):
                            ci = circles[i]
                            cj = circles[j]
                            for wall in ('L', 'R', 'B', 'T'):
                                cands = candidates_WCC(ci, cj, W, H, wall, circles)
                                for (x, y, r) in cands:
                                    if r > best_r + 1e-12 and nonoverlap_with_all(x, y, r, circles, W, H, allow_tangency=True):
                                        best = (x, y, r)
                                        best_r = r

                    if best is not None and best_r > 1e-12:
                        circles.append(best)
                        continue
                    else:
                        break

                # If still not enough, fill remaining using clearance grid (fallback only)
                tries = 0
                while len(circles) < target and tries < 200:
                    tries += 1
                    kx, ky = 22, 22
                    xs = np.linspace(0.0, W, kx)
                    ys = np.linspace(0.0, H, ky)
                    best_pt = None
                    best_r = -1.0
                    for xx in xs:
                        for yy in ys:
                            rb = min(xx, W - xx, yy, H - yy)
                            if rb <= 0:
                                continue
                            for (cx, cy, cr) in circles:
                                d = math.hypot(xx - cx, yy - cy) - cr
                                if d < rb:
                                    rb = d
                                    if rb <= 0:
                                        break
                            if rb > best_r:
                                best_r = rb
                                best_pt = (xx, yy)
                    if best_pt is None or best_r <= 1e-9:
                        break
                    xx, yy = best_pt
                    rr = max(0.0, best_r - 1e-12)
                    if nonoverlap_with_all(xx, yy, rr, circles, W, H, allow_tangency=True):
                        circles.append((xx, yy, rr))
                    else:
                        xx = min(max(xx, rr), W - rr)
                        yy = min(max(yy, rr), H - rr)
                        if nonoverlap_with_all(xx, yy, rr, circles, W, H, allow_tangency=True):
                            circles.append((xx, yy, rr))
                        else:
                            break

                return np.array(circles, dtype=float)

            circles = build_with_tangencies(W, H)
            if circles.shape[0] != target:
                need = target - circles.shape[0]
                tiny = min(W, H) / 200.0
                k = int(math.ceil(math.sqrt(need)))
                xs = np.linspace(tiny, W - tiny, k + 2)[1:-1]
                ys = np.linspace(tiny, H - tiny, k + 2)[1:-1]
                pts = [(a, b) for a in xs for b in ys][:need]
                added = 0
                for (a, b) in pts:
                    ok = True
                    for (cx, cy, cr) in circles:
                        if math.hypot(a - cx, b - cy) < cr + tiny - 1e-12:
                            ok = False
                            break
                    if ok:
                        circles = np.vstack([circles, np.array([[a, b, tiny]])])
                        added += 1
                        if added >= need:
                            break
            if circles.shape[0] == target:
                min_x = np.min(circles[:, 0] - circles[:, 2])
                min_y = np.min(circles[:, 1] - circles[:, 2])
                circles[:, 0] -= min_x
                circles[:, 1] -= min_y
                max_x = np.max(circles[:, 0] + circles[:, 2])
                max_y = np.max(circles[:, 1] + circles[:, 2])
                width = max_x - min_x
                height = max_y - min_y
                if width + height <= 2.0 + 1e-9:
                    total_rad = np.sum(circles[:, 2])
                    if total_rad > best_sum:
                        best_sum = total_rad
                        best = circles.copy()

    if best is None or best.shape != (target, 3):
        # Robust fallback: tiny non-overlapping grid in 1x1
        k = 5
        xs = np.linspace(0.1, 0.9, k)
        ys = np.linspace(0.1, 0.9, k)
        centers = [(a, b) for a in xs for b in ys][:target]
        r = np.full(target, 0.02)
        best = np.column_stack([np.array([c[0] for c in centers]),
                                np.array([c[1] for c in centers]),
                                r])

    return np.asarray(best, dtype=float)

