                    if r > best_r + 1e-12 and nonoverlap_with_all(x, y, r, circles, W, H, allow_tangency=True):
                        best = cand
                        best_r = r

            # WCC: one wall + two circles
            n = len(circles)
            for i in range(n):
                for j in range(i + 1, n):
                    ci = circles[i]
                    cj = circles[j]
                    for wall in ('L', 'R', 'B', 'T'):
                        cands = candidates_WCC(ci, cj, W, H, wall, circles)
                        for (x, y, r) in cands:
                            if r > best_r + 1e-12 and nonoverlap_with_all(x, y, r, circles, W, H, allow_tangency=True):
                                best = (x, y, r)
                                best_r = r

            if best is not None and best_r > 1e-12:
                circles.append(best)
                continue
            else:
                break

        # If still not enough, fill remaining using clearance grid (fallback only)
        tries = 0
        while len(circles) < target and tries < 200:
            tries += 1
            # Grid sampling
            kx, ky = 22, 22
            xs = np.linspace(0.0, W, kx)
            ys = np.linspace(0.0, H, ky)
            best_pt = None
            best_r = -1.0
            for xx in xs:
                for yy in ys:
                    # Max admissible radius at (xx, yy)
                    rb = min(xx, W - xx, yy, H - yy)
                    if rb <= 0:
                        continue
                    for (cx, cy, cr) in circles:
                        d = math.hypot(xx - cx, yy - cy) - cr
                        if d < rb:
                            rb = d
                            if rb <= 0:
                                break
                    if rb > best_r:
                        best_r = rb
                        best_pt = (xx, yy)
            if best_pt is None or best_r <= 1e-9:
                break
            xx, yy = best_pt
            # Slight inward clamp
            rr = max(0.0, best_r - 1e-12)
            if nonoverlap_with_all(xx, yy, rr, circles, W, H, allow_tangency=True):
                circles.append((xx, yy, rr))
            else:
                # minor jitter
                xx = min(max(xx, rr), W - rr)
                yy = min(max(yy, rr), H - rr)
                if nonoverlap_with_all(xx, yy, rr, circles, W, H, allow_tangency=True):
                    circles.append((xx, yy, rr))
                else:
                    break

        return np.array(circles, dtype=float)

    # Try several aspect ratios W + H = 2
    best_sum = -1.0
    best = None
    aspect_Ws = [1.0, 1.25, 0.75, 1.35, 0.65, 1.15, 0.85]
    for W in aspect_Ws:
        H = 2.0 - W
        if H <= 0:
            continue
        circles = build_with_tangencies(W, H)

        # Safety: ensure inside bounds and non-overlap (shrink tiny if needed)
        if circles.size == 0:
            continue
        n = circles.shape[0]
        # Clamp radii to walls
        for i in range(n):
            x, y, r = circles[i]
            rmax = min(x, W - x, y, H - y)
            if r > rmax:
                circles[i, 2] = max(0.0, rmax - 1e-12)
        # Resolve tiny overlaps by shrinking the smaller circle
        for i in range(n):
            xi, yi, ri = circles[i]
            for j in range(i + 1, n):
                xj, yj, rj = circles[j]
                d = math.hypot(xi - xj, yi - yj)
                s = circles[i, 2] + circles[j, 2]
                if d < s - 1e-12:
                    over = s - d + 1e-12
                    if circles[i, 2] <= circles[j, 2]:
                        circles[i, 2] = max(0.0, circles[i, 2] - over)
                    else:
                        circles[j, 2] = max(0.0, circles[j, 2] - over)

        # If fewer than target, pad tiny circles safely
        if circles.shape[0] < target:
            need = target - circles.shape[0]
            tiny = min(W, H) / 200.0
            # Place on a small grid
            k = int(math.ceil(math.sqrt(need)))
            xs = np.linspace(tiny, W - tiny, k + 2)[1:-1]
            ys = np.linspace(tiny, H - tiny, k + 2)[1:-1]
            pts = [(a, b) for a in xs for b in ys]
            added = 0
            for (a, b) in pts:
                ok = True
                for (cx, cy, cr) in circles:
                    if math.hypot(a - cx, b - cy) < cr + tiny - 1e-12:
                        ok = False
                        break
                if ok:
                    circles = np.vstack([circles, np.array([[a, b, tiny]])])
                    added += 1
                    if added >= need:
                        break

        if circles.shape[0] != target:
            continue

        # Evaluate
        s = float(np.sum(circles[:, 2]))
        # Bounding rectangle width+height
        min_x = float(np.min(circles[:, 0] - circles[:, 2]))
        max_x = float(np.max(circles[:, 0] + circles[:, 2]))
        min_y = float(np.min(circles[:, 1] - circles[:, 2]))
        max_y = float(np.max(circles[:, 1] + circles[:, 2]))
        width = max_x - min_x
        height = max_y - min_y
        if width + height <= 2.0 + 1e-9 and s > best_sum:
            best_sum = s
            # Translate to non-negative
            circles[:, 0] -= min_x
            circles[:, 1] -= min_y
            best = circles.copy()

    if best is None or best.shape != (target, 3):
        # Robust fallback: tiny non-overlapping grid in 1x1
        k = 5
        xs = np.linspace(0.1, 0.9, k)
        ys = np.linspace(0.1, 0.9, k)
        centers = [(a, b) for a in xs for b in ys][:target]
        r = np.full(target, 0.02)
        best = np.column_stack([np.array([c[0] for c in centers]),
                                np.array([c[1] for c in centers]),
                                r])

    return np.asarray(best, dtype=float)
